const body = $input.first().json.body || $input.first().json;

const csvData = (body.csv_data || '').trim();
const instructions = (body.instructions || '').trim();
const language = (body.language || 'de').trim();

if (!csvData) {
  return [{ json: { valid: false, error: 'Keine CSV-Daten empfangen.' } }];
}

const lines = csvData.split('\n').filter(l => l.trim().length > 0);
if (lines.length < 2) {
  return [{ json: { valid: false, error: 'Bitte mindestens eine Kopfzeile und eine Datenzeile angeben.' } }];
}

if (csvData.length > 50000) {
  return [{ json: { valid: false, error: 'Daten zu groß. Bitte maximal 500 Zeilen auf einmal bereinigen.' } }];
}

return [{ json: { valid: true, csv_data: csvData, instructions, language, row_count: lines.length - 1, received_at: new Date().toISOString() } }];

const { csv_data, instructions } = $input.first().json;

const systemPrompt = 'Du bist ein Datenbereinigungsassistent. Bereinige und normalisiere die angegebenen CSV-Daten und gib das Ergebnis IMMER als valides JSON-Objekt zurueck mit genau diesen Feldern: headers (string[]), cleaned_rows (object[]), changes (string[]), stats ({total_rows, rows_modified, duplicates_removed, issues_found}).';

const userContent = 'Bereinige und normalisiere diese CSV-Daten.\n\n'
  + (instructions ? 'Spezielle Anweisungen: ' + instructions + '\n\n' : '')
  + 'Folgende Bereinigungen durchfuehren:\n'
  + '- Fuehrende und nachfolgende Leerzeichen entfernen\n'
  + '- E-Mail-Adressen auf Kleinbuchstaben normalisieren und auf Gueltigkeit pruefen\n'
  + '- Telefonnummern in einheitliches Format bringen\n'
  + '- Namen korrekt kapitalisieren\n'
  + '- Firmennamen konsistent machen\n'
  + '- Exakte Duplikate und aehnliche Duplikate entfernen (behalte vollstaendigere Zeile)\n'
  + '\nCSV-DATEN:\n' + csv_data
  + '\n\nGib zurueck: {"headers": [...], "cleaned_rows": [{...}], "changes": ["..."], "stats": {"total_rows": N, "rows_modified": N, "duplicates_removed": N, "issues_found": N}}';

const kimiRequest = {
  model: 'kimi-k2.5',
  max_tokens: 4096,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userContent }
  ]
};

return [{ json: { kimiRequest, received_at: $input.first().json.received_at } }];

const meta = $('Anfrage aufbauen').first().json;
const response = $input.first().json;

const content = response.choices?.[0]?.message?.content;
if (!content) throw new Error('KI returned empty response');

let data;
try {
  data = JSON.parse(content);
} catch {
  const match = content.match(/```(?:json)?\s*([\s\S]+?)```/);
  if (!match) throw new Error('Could not parse JSON from KI response: ' + content.substring(0, 200));
  data = JSON.parse(match[1]);
}

const { headers, cleaned_rows, changes, stats } = data;
const csvLines = [headers.join(',')];
for (const row of cleaned_rows) {
  const values = headers.map(h => {
    const val = (row[h] || '').toString();
    return val.includes(',') || val.includes('"') || val.includes('\n')
      ? '"' + val.replace(/"/g, '""') + '"'
      : val;
  });
  csvLines.push(values.join(','));
}

return [{ json: { headers, cleaned_rows, changes, stats, cleaned_csv: csvLines.join('\n'), received_at: meta.received_at } }];
